<script lang="ts">
  import { onMount } from 'svelte';
  let completion = $state(0); let scheduled = $state(0); let conducted = $state(0); let syllabus = $state(0);
  let periodLabel = $state(''); let status = $state('Draft'); let dueDate = $state('');
  let reports: { label: string; status: string; completion: number; updated_at: string }[] = $state([]);
  let loading = $state(true); let error = $state('');
  onMount(async () => {
    try {
      const response = await fetch('/api/dashboard');
      const data = await response.json();
      if (!response.ok) { error = 'Unable to load dashboard data.'; return; }
      completion = data.report?.completion ?? 0; scheduled = data.stats?.scheduled ?? 0;
      conducted = data.stats?.conducted ?? 0; syllabus = data.stats?.syllabus ?? 0;
      periodLabel = data.report?.label ?? ''; dueDate = data.report?.due_on ?? '';
      status = data.report?.status === 'SUBMITTED' ? 'Submitted' : data.report?.status === 'APPROVED' ? 'Approved' : data.report?.status === 'CHANGES_REQUIRED' ? 'Changes required' : data.report?.status ? 'Draft' : 'No report';
      const reportsRes = await fetch('/api/reports');
      const reportsData = await reportsRes.json();
      if (reportsData.report) {
        reports = [{ label: periodLabel, status: status, completion: completion, updated_at: new Date().toISOString() }];
      }
    } catch { error = 'Unable to connect to the server.'; }
    finally { loading = false; }
  });
  const deadline = $derived(dueDate ? new Date(dueDate).toLocaleString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: 'numeric', minute: '2-digit' }) : '');
  const deliveryRate = $derived(scheduled ? Math.round((conducted / scheduled) * 100) : null);
</script>
<svelte:head><title>Dashboard · Faculty Reporting System</title></svelte:head>
<main class="shell app-shell formal-dashboard">
  <div class="breadcrumb">Faculty workspace <span>/</span> Dashboard</div>
  <section class="formal-header"><div><div class="eyebrow">Faculty reporting system</div><h1>Dashboard</h1><p>Reporting overview for Faculty member, Department of Computer Science and Engineering.</p></div><div class="header-meta"><span>Academic year</span><strong>2026–27</strong></div></section>
  {#if loading}
    <div class="loading-panel"><span class="spinner"></span><span>Loading dashboard…</span></div>
  {:else if error}
    <div class="error-panel">{error}</div>
  {:else}
  <section class="period-banner"><div><span class="eyebrow">Active reporting period</span><h2>{periodLabel || 'Current week'}</h2><p>Weekly teaching activity report{deadline ? ` · Submission deadline: ${deadline}` : ''}</p></div><div class="period-progress"><div><span>Completion</span><strong>{completion}%</strong></div><div class="formal-track"><i style="width:{completion}%"></i></div><a href="/reports/current">{status === 'Approved' ? 'View report' : status === 'Submitted' ? 'View submitted report' : 'Continue report'} <span>→</span></a></div></section>
  <section class="summary-strip" aria-label="Report summary"><div><span>Courses this week</span><strong>{scheduled ? Math.max(1, Math.round(conducted / Math.max(1, scheduled) * 10)) : 0}</strong><small>Active courses</small></div><div><span>Classes conducted</span><strong>{conducted} / {scheduled}</strong><small>{deliveryRate !== null ? `${deliveryRate}% delivery` : 'No classes scheduled'}</small></div><div><span>Syllabus progress</span><strong>{syllabus}%</strong><small>Across current courses</small></div><div><span>Report status</span><strong class="status-label" class:draft={status === 'Draft'} class:submitted={status === 'Submitted'} class:approved={status === 'Approved'} class:changes={status === 'Changes required'}>{status}</strong><small>{periodLabel || 'No active period'}</small></div></section>
  <section class="dashboard-grid"><div class="data-panel"><div class="panel-heading"><div><h2>Recent weekly reports</h2><p>Teaching-report history for the current academic year.</p></div><a href="/reports">View report history</a></div><table><thead><tr><th>Reporting period</th><th>Status</th><th>Last updated</th><th class="align-right">Action</th></tr></thead><tbody>{#if !reports.length}<tr><td colspan="4" class="empty-row">No reports found for this period.</td></tr>{:else}{#each reports as report}<tr><td><strong>{report.label}</strong><small>Current week</small></td><td><span class="status-label {report.status.toLowerCase().replace(' ', '_')}">{report.status}</span></td><td>{new Date(report.updated_at).toLocaleDateString()}</td><td class="align-right"><a href="/reports/current">Open</a></td></tr>{/each}{/if}</tbody></table></div><aside class="attention-panel"><div class="panel-heading"><div><h2>Attention required</h2><p>Items that may need your action.</p></div></div>{#if !reports.length && !loading}<div class="attention-item"><span class="attention-mark info">i</span><div><strong>No active report period</strong><p>There is no open reporting period right now.</p></div></div>{:else if status === 'Draft' || status === 'No report'}<div class="attention-item"><span class="attention-mark warning">!</span><div><strong>Current weekly report is incomplete</strong><p>Add this week's teaching activity and review it before submission.</p><a href="/reports/current">Review report →</a></div></div>{:else if status === 'Submitted'}<div class="attention-item"><span class="attention-mark info">i</span><div><strong>Report under review</strong><p>Your weekly report has been submitted. Your HOD will review it shortly.</p><a href="/reports/current">View submitted report →</a></div></div>{:else if status === 'Approved'}<div class="attention-item"><span class="attention-mark success">✓</span><div><strong>Report approved</strong><p>Your weekly report for {periodLabel} has been approved by your HOD.</p><a href="/reports/current">View report →</a></div></div>{:else if status === 'Changes required'}<div class="attention-item"><span class="attention-mark warning">!</span><div><strong>Changes requested by HOD</strong><p>Your HOD has requested changes to your weekly report. Please review their feedback.</p><a href="/reports/current">Review feedback →</a></div></div>{/if}{#if deadline && (status === 'Draft' || status === 'No report')}<div class="attention-item"><span class="attention-mark info">i</span><div><strong>Submission deadline</strong><p>{deadline}.</p><a href="/reports/current">Open report →</a></div></div>{/if}</aside></section>
  {/if}
</main>
