ze:.72rem}.summary-strip strong{display:block;font-size:1.6rem;letter-spacing:-.04em;margin:6px 0 2px}.status-label{display:inline-block;padding:4px 8px;border-radius:3px;font-size:.65rem;font-weight:800}.draft{background:#f7ead2;color:#97651b}.submitted{background:#e2e8ec;color:#536871}.approved{background:#dff2ec;color:#0f766e}.changes{background:#f7ead2;color:#97651b}.dashboard-grid{display:grid;grid-template-columns:1.55fr .85fr;gap:20px}.data-panel,.attention-panel{background:#fdfcf9;border:1px solid #dbe3e7;border-radius:7px}.panel-heading{display:flex;justify-content:space-between;align-items:start;gap:20px;padding:18px 20px;border-bottom:1px solid #dbe3e7}.panel-heading h2{font-size:1rem;margin:0}.panel-heading p{font-size:.76rem;color:#71818a;margin:4px 0 0}.data-panel table{width:100%;border-collapse:collapse;font-size:.78rem}.data-panel th{text-align:left;text-transform:uppercase;letter-spacing:.08em;color:#87969c;font-size:.64rem;font-weight:800}.data-panel th,.data-panel td{padding:14px 20px;border-bottom:1px solid #e6ecee}.data-panel tbody tr:last-child td{border-bottom:0}.data-panel td{color:#61727d}.data-panel td strong,.data-panel td small{display:block}.data-panel td strong{color:#1b2b36}.data-panel td small{font-size:.7rem;color:#87969c;margin-top:3px}.align-right{text-align:right}.empty-row{text-align:center;padding:24px;color:#87969c;font-size:.8rem}.attention-item{display:flex;gap:11px;padding:17px 20px;border-bottom:1px solid #e6ecee}.attention-item:last-child{border-bottom:0}.attention-mark{width:21px;height:21px;border-radius:50%;display:grid;place-items:center;font-weight:800;font-size:.72rem;flex:none}.attention-mark.warning{background:#fff0d2;color:#9a6414}.attention-mark.info{background:#e6f0f4;color:#3a7083}.attention-mark.success{background:#dff2ec;color:#0f766e}.attention-item strong{display:block;font-size:.8rem}.attention-item p{color:#71818a;font-size:.74rem;line-height:1.45;margin:5px 0 8px}@media(max-width:850px){.period-banner,.